/**
 * COR-2770: a `collapseBelow` other than 640px brings the phone form in a `<style>` of its own,
 * generated by `phoneFormStyle`. These hold that CSS to the declarations `breadcrumbs.css` gives the
 * default 640px, so the two can never draw different phone forms.
 */
import { describe, expect, test } from 'bun:test';

import { atRuleDeclarationsFor } from '@lostgradient/component-tooling/test/css.ts';
import { parse } from 'postcss';

import { PHONE_FORM_RULES, phoneFormScope, phoneFormStyle } from './breadcrumbs-phone-form.ts';

const stylesheet = await Bun.file(new URL('./breadcrumbs.css', import.meta.url)).text();

describe('Breadcrumbs phone form for another collapseBelow', () => {
  test('uses that length in its query and its selector, in the component layer', () => {
    const css = phoneFormStyle('48rem');
    const layers: string[] = [];
    const queries: string[] = [];
    const selectors: string[] = [];
    const root = parse(css);
    root.walkAtRules('layer', (rule) => void layers.push(rule.params));
    root.walkAtRules('media', (rule) => void queries.push(rule.params));
    root.walkRules((rule) => void selectors.push(rule.selector));

    expect(layers).toEqual(['cinder.components']);
    expect(queries).toEqual(['not all and (min-width: 48rem)']);
    expect(selectors).toHaveLength(PHONE_FORM_RULES.length);
    for (const selector of selectors) {
      expect(selector.startsWith('.cinder-breadcrumbs[data-cinder-phone-below="48rem"]')).toBe(
        true,
      );
    }
    expect(css).not.toContain('<');
  });

  test('declares exactly what breadcrumbs.css declares for 640px', () => {
    const generated = phoneFormStyle('640px');
    const scope = phoneFormScope('640px');
    const stylesheetScope = ".cinder-breadcrumbs[data-cinder-phone-below='640px']";
    for (const [selector] of PHONE_FORM_RULES) {
      const fromStylesheet = atRuleDeclarationsFor(
        stylesheet,
        'media',
        '(width < 640px)',
        `${stylesheetScope}${selector}`,
      );
      const fromGenerated = atRuleDeclarationsFor(
        generated,
        'media',
        'not all and (min-width: 640px)',
        `${scope}${selector}`,
      );
      expect(fromStylesheet.size).toBeGreaterThan(0);
      expect([...fromGenerated]).toEqual([...fromStylesheet]);
    }
  });

  test('the stylesheet has no phone-form rule the generated CSS lacks', () => {
    const stylesheetSelectors: string[] = [];
    parse(stylesheet).walkAtRules('media', (rule) => {
      if (rule.params !== '(width < 640px)') return;
      rule.walkRules(
        (inner) => void stylesheetSelectors.push(inner.selector.replace(/\s+/g, ' ').trim()),
      );
    });
    expect(stylesheetSelectors).toEqual(
      PHONE_FORM_RULES.map(
        ([selector]) => `.cinder-breadcrumbs[data-cinder-phone-below='640px']${selector}`,
      ),
    );
  });
});
